=== write test ===
import { spawn, type ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'

import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { expectedTestLinkMcp } from '../src/mcp-testlink-client.js'

/**
 * What this proves: a Test Case submitted through the running server lands in a
 * real TestLink, and the id the write answers with is the id a read of that
 * TestLink answers to.
 *
 * And the same write refused: a clean Test Case addressed to a Test Suite
 * TestLink does not hold is answered as the caller's own mistake — a 404 naming
 * what is missing, carrying no violations — and TestLink holds no new Test Case
 * anywhere afterwards. That claim is about wording rather than about a status
 * code: `McpTestLinkClient` decides between absence and an outage by matching
 * the words TestLink failed in, and every other file here matches that reading
 * against strings the suite itself wrote. Only a real TestLink can say whether
 * the words it actually fails in are the words being matched.
 *
 * It is the one thing the rest of the suite cannot say. Every other file here
 * substitutes TestLink — `stub-testlink-client.ts` — or Postgres — `pg-mem` —
 * and none of them imports `src/server.ts` at all, so an id invented in the
 * answer and never stored would pass all of them. This file starts the real
 * entry point the way `npm run dev` does, and every hop below it is the real
 * one: the real testlink-mcp container, the real TestLink, the real database.
 *
 * Nothing is substituted. One thing is configured rather than defaulted, and it
 * is named here because it is the seam that would otherwise be silent:
 * `src/server.ts` launches testlink-mcp in a container with no `--network`
 * flag, which cannot reach a TestLink published on the host's own localhost —
 * the address `.env.example` documents and `.mcp.json` uses. So the launch is
 * overridden with the host-network form `.mcp.json` already carries, through
 * the two settings the server reads for exactly this purpose. The version is
 * imported from the client rather than restated, so it cannot drift from the
 * testlink-mcp the client is written against. Set TESTLINK_MCP_COMMAND and
 * TESTLINK_MCP_ARGS in the environment to launch it some other way.
 *
 * What it needs, none of which it creates for itself:
 *
 *   docker compose up -d
 *   psql "$DATABASE_URL" -f schema.sql
 *   psql "$DATABASE_URL" -f default-rules.sql
 *
 * and a `.env` naming that database, that TestLink and an API key for it. With
 * any of them absent this file fails rather than skips: it exists to be the
 * check that cannot pass while the real path is broken.
 */

/** Where this run's server listens. Not 3000 or the .env PORT: a server already up is not this one. */
const port = Number(process.env.SYSTEM_TEST_PORT ?? 8131)
const server = `http://127.0.0.1:${port}`

const repository = fileURLToPath(new URL('..', import.meta.url))

/**
 * The fixture Project and Test Suite this write is placed in, and the Test Case
 * it writes. Stable names, never suffixed: a run that dies before its teardown
 * leaves them findable, so the next run reuses what it finds instead of filling
 * TestLink with near-duplicates. The prefix is stamped into the Project forever
 * and TestLink will not have two, which is another reason not to generate one.
 */
const fixture = {
  project: { name: 'Validator System Test', prefix: 'VSTX' },
  suite: { name: 'Write and read back' },
  /**
   * Wording chosen to violate none of the shipped Rules — no colon, no hyphen,
   * none of the terms in `default-rules.sql` — because a Rejection is a 422 and
   * this file is not about what the Rules do. If the Rules grow to catch this,
   * the failure says so: the body of a 422 names the Rule that fired.
   */
  testCase: {
    name: 'Guest device joins the open SSID',
    summary: 'A guest device associates with the open SSID and loads the portal page.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /**
   * The Test Suite that supplies an id TestLink does not hold. It is placed and
   * then removed, so the id handed on is one TestLink issued and has given up,
   * rather than a number picked for being free — a number free today is a
   * number some later run finds taken, and a check against one is a check
   * against arithmetic instead of against absence.
   */
  removedSuite: { name: 'Removed so its id is held by nothing' },
  /**
   * The Test Case addressed to that id. A name of its own rather than the one
   * above, because the claim is that TestLink holds no Test Case under it and
   * the write above puts that one in the fixture Suite on purpose. Worded to
   * violate no shipped Rule for the same reason as the write: a Rejection is a
   * 422 and would never reach TestLink at all.
   */
  refusedCase: {
    name: 'Guest device roams between access points',
    summary: 'A guest device moves between two access points and keeps the portal session.',
    preconditions: 'Both access points broadcast the open SSID.',
  },
}

/** What the server answered, kept whole so a failure can quote it. */
interface Answer {
  status: number
  text: string
  body: any
}

async function call(method: string, path: string, payload?: unknown): Promise<Answer> {
  const response = await fetch(`${server}${path}`, {
    method,
    ...(payload === undefined
      ? {}
      : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }),
  })
  const text = await response.text()

  return { status: response.status, text, body: text === '' ? undefined : JSON.parse(text) }
}

/**
 * The answer, or a failure naming what was asked and what came back. Written as
 * a throw rather than an expectation so the same reading works in a hook: a
 * TestLink that is not answering has to say so where it happened, not as an
 * undefined further down.
 */
function answered(what: string, answer: Answer, status: number): Answer {
  if (answer.status !== status) {
    throw new Error(`${what} answered ${answer.status} rather than ${status}: ${answer.text}`)
  }

  return answer
}

/**
 * A listing, reading a Project or a Test Suite that holds nothing yet as the
 * empty listing it is.
 *
 * TestLink reports "is empty" as an API failure rather than as an empty result,
 * and `McpTestLinkClient` matches only "does not exist" and "not found", so that
 * wording escalates as an outage and the server answers 500. That is worth an
 * issue of its own and it is not what this file is about: it shows up only on
 * the way to placing the fixture, on the first run against a TestLink that has
 * never held it. Read here, in the fixture path alone — every answer the claim
 * itself reads is demanded outright.
 */
function listed(what: string, answer: Answer): { id: string; name: string }[] {
  if (answer.status === 500 && /is empty/i.test(answer.text)) {
    return []
  }

  return answered(what, answer, 200).body as { id: string; name: string }[]
}

let serverProcess: ChildProcess
/** Everything the server said, so a start that never completes reports its own reason. */
let said = ''
let projectId: string
let suiteId: string
let absentSuiteId: string
let writtenId: string | undefined

/** The real entry point, launched the way `npm run dev` launches it. */
async function startServer(): Promise<void> {
  serverProcess = spawn('npx', ['tsx', '--env-file-if-exists=.env', 'src/server.ts'], {
    cwd: repository,
    // Set here rather than in .env: what is set in the environment wins over the
    // file, so this names the port and the launch without editing anything.
    env: {
      ...process.env,
      PORT: String(port),
      TESTLINK_MCP_COMMAND: process.env.TESTLINK_MCP_COMMAND ?? 'docker',
      TESTLINK_MCP_ARGS:
        process.env.TESTLINK_MCP_ARGS ??
        JSON.stringify([
          'run',
          '--rm',
          '-i',
          '--network',
          'host',
          '-e',
          'TESTLINK_URL',
          '-e',
          'TESTLINK_API_KEY',
          `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
        ]),
    },
    // Its own group, so stopping it stops the testlink-mcp it spawned as well.
    detached: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })

  serverProcess.stdout?.on('data', (chunk) => (said += chunk))
  serverProcess.stderr?.on('data', (chunk) => (said += chunk))

  // Readiness is asked of the route that reads only the database, so a TestLink
  // that is down is reported by the step that needed it rather than as a server
  // that never started.
  for (let attempt = 0; attempt < 120; attempt++) {
    if (serverProcess.exitCode !== null) {
      throw new Error(`The server exited with ${serverProcess.exitCode} before it listened: ${said}`)
    }

    try {
      await call('GET', '/reference-documents')
      return
    } catch {
      await new Promise((wait) => setTimeout(wait, 500))
    }
  }

  throw new Error(`The server did not listen on ${port}: ${said}`)
}

function stopServer(): void {
  if (serverProcess?.pid !== undefined && serverProcess.exitCode === null) {
    try {
      process.kill(-serverProcess.pid, 'SIGTERM')
    } catch {
      serverProcess.kill('SIGTERM')
    }
  }
}

/** The fixture Project, reused where TestLink already holds one under this name. */
async function placeProject(): Promise<string> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)
  const held = (projects.body as { id: string; name: string }[]).find(
    (project) => project.name === fixture.project.name,
  )

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Project ${fixture.project.name}`,
    await call('POST', '/projects', {
      ...fixture.project,
      notes: 'Fixture Project for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/** The fixture Test Suite under it, reused the same way and for the same reason. */
async function placeSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.suite.name)

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Test Suite ${fixture.suite.name}`,
    await call('POST', `/projects/${projectId}/suites`, {
      ...fixture.suite,
      details: 'Fixture Test Suite for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/**
 * A Test Suite id TestLink no longer holds. Placed under the fixture Project and
 * removed again, because absence has to be something TestLink demonstrated
 * rather than something this file assumed: TestLink issues node ids from a
 * sequence and does not issue one twice, so an id it has given up is an id it
 * will never hold again.
 *
 * The name is stable and never suffixed, so a run that died between the place
 * and the remove leaves a Test Suite the next run finds and removes rather than
 * a second one beside it. The removal is verified before the id is handed on,
 * because an id whose Test Suite is still there would prove the opposite of what
 * the claim needs and would do it silently.
 */
async function placeAndRemoveSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.removedSuite.name)

  const id =
    held !== undefined
      ? String(held.id)
      : String(
          answered(
            `Creating Test Suite ${fixture.removedSuite.name}`,
            await call('POST', `/projects/${projectId}/suites`, {
              ...fixture.removedSuite,
              details:
                'Placed and removed by the system test, so that its id is one TestLink holds nothing under.',
            }),
            201,
          ).body.id,
        )

  answered(
    `Removing Test Suite ${id}`,
    await call('DELETE', `/projects/${projectId}/suites/${id}`),
    204,
  )

  const remaining = listed(
    `Listing the Test Suites of Project ${projectId} after removing ${id}`,
    await call('GET', `/projects/${projectId}/suites`),
  )

  if (remaining.some((suite) => String(suite.id) === id)) {
    throw new Error(`Test Suite ${id} is still in Project ${projectId}, so its id is not free.`)
  }

  return id
}

/**
 * How many Test Cases TestLink has issued an id for, per Project — its own
 * count, served with every Project it lists. A count that has not moved in any
 * Project is TestLink having created no Test Case anywhere, which is what the
 * refusal below has to be true of and what listing one Test Suite cannot say.
 */
async function testCaseCounts(): Promise<Record<string, string>> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)

  return Object.fromEntries(
    (projects.body as { id: string; tc_counter: string }[]).map((project) => [
      String(project.id),
      String(project.tc_counter),
    ]),
  )
}

/**
 * A Test Case this fixture name is already on, from a run that failed before its
 * teardown. Removed rather than written beside, so the write below is the only
 * one under that name and a leak cannot accumulate.
 */
async function removeLeftovers(): Promise<void> {
  const cases = listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  )

  for (const held of cases) {
    if (held.name === fixture.testCase.name) {
      answered(
        `Removing the leftover Test Case ${held.id}`,
        await call('DELETE', `/test-cases/${held.id}`),
        204,
      )
    }
  }
}

describe('a Test Case written through the running server', () => {
  beforeAll(async () => {
    await startServer()
    projectId = await placeProject()
    suiteId = await placeSuite()
    absentSuiteId = await placeAndRemoveSuite()
    await removeLeftovers()
  }, 120_000)

  afterAll(async () => {
    try {
      if (writtenId !== undefined) {
        answered(
          `Removing the Test Case ${writtenId} this run created`,
          await call('DELETE', `/test-cases/${writtenId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${writtenId}`,
          await call('GET', `/test-cases/${writtenId}`),
          404,
        )
      }
    } finally {
      stopServer()
    }
  }, 60_000)

  it('lands in TestLink under the id the write answered with', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.testCase),
      201,
    )

    writtenId = String(written.body.id)
    expect(writtenId).not.toBe('')

    // The id is TestLink's own, not one this answer minted: TestLink's tree
    // reports the Test Case under it, with the Fields that were sent.
    const inSuite = answered(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
      200,
    )
    expect((inSuite.body as { id: string }[]).map((held) => String(held.id))).toContain(writtenId)

    // And the read the API serves answers to that same id, with what was
    // written rather than with what the write was told.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.testCase)
  }, 60_000)

  it('is refused as absence when TestLink holds no such Test Suite, and writes nothing', async () => {
    const before = await testCaseCounts()

    // Demanded as a 404 rather than read for one: how the failure is worded is
    // the claim, so a run that gets some other answer has to quote what TestLink
    // actually said. A 500 here is `McpTestLinkClient` failing to recognise
    // TestLink's own wording for a Test Suite that is not there, and a 422 is a
    // Rule having fired on the Test Case before TestLink was ever reached.
    const refused = answered(
      `Submitting to Test Suite ${absentSuiteId}, which TestLink does not hold`,
      await call('POST', `/projects/${projectId}/suites/${absentSuiteId}/test-cases`, fixture.refusedCase),
      404,
    )

    // Nothing was refused, so nothing is reported as refused: an answer carrying
    // violations would be a Rejection, and this caller has an id to correct
    // rather than wording to fix.
    expect(refused.body).not.toHaveProperty('violations')
    expect(refused.body.message).toContain(absentSuiteId)

    // The infrastructure, which is what separates this from a status code any
    // substitute could produce: TestLink issued no Test Case id in any Project,
    // and the Test Suite the write would have landed in holds nothing under the
    // name that was sent.
    expect(await testCaseCounts()).toEqual(before)

    const inSuite = listed(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
    )
    expect(inSuite.map((held) => held.name)).not.toContain(fixture.refusedCase.name)
  }, 60_000)
})

