 * count, served with every Project it lists. A count that has not moved in any
 * Project is TestLink having created no Test Case anywhere, which is what the
 * refusal below has to be true of and what listing one Test Suite cannot say.
 */
async function testCaseCounts(): Promise<Record<string, string>> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)

  return Object.fromEntries(
    (projects.body as { id: string; tc_counter: string }[]).map((project) => [
