  beforeAll(async () => {
    await startServer()
    projectId = await placeProject()
    suiteId = await placeSuite()
    absentSuiteId = await placeAndRemoveSuite()
    await removeLeftovers()
  }, 120_000)

  afterAll(async () => {
    try {
      if (writtenId !== undefined) {
        answered(
          `Removing the Test Case ${writtenId} this run created`,
          await call('DELETE', `/test-cases/${writtenId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${writtenId}`,
          await call('GET', `/test-cases/${writtenId}`),
          404,
        )
      }
    } finally {
      stopServer()
    }
  }, 60_000)

  it('lands in TestLink under the id the write answered with', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.testCase),
      201,
    )

