    // reports the Test Case under it, with the Fields that were sent.
    const inSuite = answered(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
      200,
    )
    expect((inSuite.body as { id: string }[]).map((held) => String(held.id))).toContain(writtenId)

    // And the read the API serves answers to that same id, with what was
    // written rather than with what the write was told.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.testCase)
  }, 60_000)

  it('is refused as absence when TestLink holds no such Test Suite, and writes nothing', async () => {
    const before = await testCaseCounts()

    // Demanded as a 404 rather than read for one: how the failure is worded is
    // the claim, so a run that gets some other answer has to quote what TestLink
    // actually said. A 500 here is `McpTestLinkClient` failing to recognise
    // TestLink's own wording for a Test Suite that is not there, and a 422 is a
    // Rule having fired on the Test Case before TestLink was ever reached.
    const refused = answered(
      `Submitting to Test Suite ${absentSuiteId}, which TestLink does not hold`,
      await call('POST', `/projects/${projectId}/suites/${absentSuiteId}/test-cases`, fixture.refusedCase),
      404,
    )

    // Nothing was refused, so nothing is reported as refused: an answer carrying
    // violations would be a Rejection, and this caller has an id to correct
    // rather than wording to fix.
    expect(refused.body).not.toHaveProperty('violations')
    expect(refused.body.message).toContain(absentSuiteId)

