    // substitute could produce: TestLink issued no Test Case id in any Project,
    // and holds nothing in the fixture Test Suite under the name that was sent.
    expect(await testCaseCounts()).toEqual(before)
    expect(await namesInSuite()).not.toContain(fixture.refused.name)
  }, 60_000)

  it('carries an accepted update through to what TestLink holds', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.written),
      201,
    )

    writtenId = String(written.body.id)
    expect(writtenId).not.toBe('')

    answered(
      `Updating Test Case ${writtenId}`,
      await call('PUT', `/test-cases/${writtenId}`, fixture.updated),
      200,
    )

    // TestLink's own tree, which is a different call from the read below: the
    // Test Case is under the new name there and no longer under the old one, so
    // the update reached TestLink rather than only the answer.
    const names = await namesInSuite()
    expect(names).toContain(fixture.updated.name)
    expect(names).not.toContain(fixture.written.name)

    // And every Field TestLink now holds is the Field that was sent, read back
    // under the same id the write answered with.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.updated)
  }, 60_000)

  it('refuses an update a shipped Rule catches, and TestLink keeps what it had', async () => {
    if (writtenId === undefined) {
      throw new Error('The Test Case this path updates was never written, so there is nothing to refuse.')
    }

    const rejected = answered(
      `Updating Test Case ${writtenId} to wording the ${shippedRule.id} Rule catches`,
      await call('PUT', `/test-cases/${writtenId}`, fixture.refused),
      422,
    )

    expect(rejected.body.violations).toContainEqual(
      expect.objectContaining({ field: shippedRule.field, rule: shippedRule.id }),
    )

    // The infrastructure: TestLink holds what the accepted update put there, and
    // holds nothing under the refused wording. A Rejection that reached TestLink
    // and was then reported as a refusal would pass every other file here.
    const read = answered(
      `Reading Test Case ${writtenId} after the refused update`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.updated)
    expect(await namesInSuite()).not.toContain(fixture.refused.name)
  }, 60_000)

  it('reads a Test Suite TestLink does not hold as absence rather than as an outage', async () => {
    // The id really is one TestLink holds nothing under: it issued it, and the
    // Project's own Test Suite listing no longer reports it.
    expect(await suiteIdsInProject()).not.toContain(absentSuiteId)

    const answer = await call('GET', `/projects/${projectId}/suites/${absentSuiteId}/test-cases`)

    // Demanded as a 404 rather than read for one: how TestLink words the failure
    // is the claim. A 500 here is `McpTestLinkClient.reportsAbsence` failing to
    // recognise TestLink's own wording for a Test Suite that is not there, which
    // sends a caller with a correctable id an outage to escalate instead.
    answered(
      `Listing the Test Cases of Test Suite ${absentSuiteId}, which TestLink does not hold`,
      answer,
      404,
    )

    // Nothing was refused, so nothing is reported as refused: an answer carrying
    // violations would be a Rejection, and this caller has an id to correct.
    expect(answer.body).not.toHaveProperty('violations')
    expect(answer.body.message).toContain(absentSuiteId)
  }, 60_000)

  it('refuses to update a Test Suite TestLink does not hold, and creates nothing', async () => {
    const before = await suiteIdsInProject()
    expect(before).not.toContain(absentSuiteId)

    const answer = await call('PUT', `/projects/${projectId}/suites/${absentSuiteId}`, {
      details: 'Written by the system test to a Test Suite that is not there.',
    })

    // An update answered as applied to a Test Suite TestLink does not hold is a
    // confirmation of something that did not happen, and a caller that reads it
    // stops looking for the id it got wrong.
    answered(
      `Updating Test Suite ${absentSuiteId}, which TestLink does not hold`,
      answer,
      404,
    )
    expect(answer.body.message).toContain(absentSuiteId)

    // The infrastructure: the Project holds exactly the Test Suites it held
    // before, so the update neither revived that id nor made a Test Suite
    // anywhere else.
    expect(await suiteIdsInProject()).toEqual(before)
  }, 60_000)

  it('refuses to delete a Test Suite TestLink does not hold, and removes nothing', async () => {
    const before = await suiteIdsInProject()
    expect(before).not.toContain(absentSuiteId)

    const answer = await call('DELETE', `/projects/${projectId}/suites/${absentSuiteId}`)

    answered(
      `Deleting Test Suite ${absentSuiteId}, which TestLink does not hold`,
      answer,
      404,
    )
    expect(answer.body.message).toContain(absentSuiteId)

    // The infrastructure: the fixture Test Suite is still there. A delete aimed
    // at an id nothing is held under must not take something else with it.
    const after = await suiteIdsInProject()
    expect(after).toEqual(before)
    expect(after).toContain(suiteId)
  }, 60_000)
})

