import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

import { newDb } from 'pg-mem'

import { queriesFrom } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'

/**
 * A file the repository ships, read rather than restated, so a test of what an
 * operator is told to do fails when what they are told changes. The operator
 * applies these by hand and nothing this project runs writes a row (ADR-0006),
 * so a test of them has to be a test of the files themselves — statements copied
 * in here would pass while the file an operator applies was broken.
 */
export function shipped(name: string): string {
  return readFileSync(fileURLToPath(new URL(`../${name}`, import.meta.url)), 'utf8')
}

/**
 * A Postgres that runs in this process, holding no tables until the schema is
 * applied — a database an operator has not set up yet. The stubbed seam beside
 * this one proves the store asks for the right things; this one proves the
 * statements it asks with are statements a Postgres accepts — the schema, the
 * parameters and the reading of rows, none of which a stub can tell the truth
 * about.
 */
export function empty(): Queries {
  const pg = newDb().adapters.createPg()

  // Through the production adapter, not a copy of it, so what the tests
  // exercise is the same reading of rows the server does.
  return queriesFrom(new pg.Client())
}
=== queries.ts ===
/**
 * The path to the database, one statement at a time. Narrow on purpose: it is
 * the seam that lets the real store be exercised — the statements it runs, the
 * parameters it sends, and how it reads what comes back — without a database.
 *
 * Parameters are sent separately from the statement rather than written into
 * it, so a document id a caller supplies is data and never SQL.
 */
export interface Queries {
  run(sql: string, parameters?: unknown[]): Promise<Record<string, unknown>[]>
}

