import { spawn, type ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'

import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { expectedTestLinkMcp } from '../src/mcp-testlink-client.js'

/**
 * What this proves: the two ways the server refuses to destroy a Project, and the
 * two absences it reads out of TestLink's own words on the Project and Test Case
 * routes rather than the Test Suite ones.
 *
 * Four paths, each a caller action and what must be true of TestLink after it:
 *
 *   1. Deleting a Project with the wrong prefix restated is the caller's own
 *      mistake — a 409 — and the Project, its Test Suite and its Test Case are
 *      all still there afterwards. `McpTestLinkClient.deleteProject` decides
 *      this by matching the words TestLink refuses the interlock in
 *      (`reportsUnconfirmed` looks for "Confirmation failed"), and it is checked
 *      before absence so a wrong prefix is never reported as a missing Project.
 *   2. Deleting a Project with no prefix restated at all is refused by the
 *      schema, before any tool call is made, and the same tree survives. A
 *      schema refusal carries `refusal: 'schema'` and no violations, so it
 *      cannot be read as a Rejection.
 *   3. Reading a Test Case under an id TestLink has given up is absence rather
 *      than an outage, and nothing else in the Test Suite went with it.
 *   4. Updating a Project TestLink does not hold is absence rather than an
 *      applied change, and the Project listing is exactly what it was — an
 *      update reported as applied to a Project that is not there is a
 *      confirmation of something that did not happen.
 *
 * Paths 1, 3 and 4 are about wording rather than about status codes. Every other
 * file in this suite matches `reportsUnconfirmed` and `reportsAbsence` against
 * strings the suite itself wrote; only a real TestLink can say whether the words
 * it actually refuses and fails in are the words being matched. Paths 3 and 4
 * are deliberately on the Test Case and Project routes rather than the Test
 * Suite ones `system-refusals-reach-testlink.test.ts` already covers, because
 * those are red and this is how wide that defect is: if these two pass, TestLink
 * words an absent Test Suite differently from an absent Test Case, and the
 * regex is short by one wording rather than wrong in principle.
 *
 * Nothing is substituted. One thing is configured rather than defaulted, and it
 * is the same seam the two files beside this one name: `src/server.ts` launches
 * testlink-mcp in a container with no `--network` flag, which cannot reach a
 * TestLink published on the host's own localhost. So the launch is overridden
 * with the host-network form, through the two settings the server reads for
 * exactly that purpose, and the version is imported from the client so it
 * cannot drift from the testlink-mcp the client is written against.
 *
 * What it needs, none of which it creates for itself:
 *
 *   docker compose up -d
 *   psql "$DATABASE_URL" -f schema.sql
 *   psql "$DATABASE_URL" -f default-rules.sql
 *
 * and a `.env` naming that database, that TestLink and an API key for it. With
 * any of them absent this file fails rather than skips.
 *
 * Run the system files with `--no-file-parallelism`. Not for this file's sake —
 * it asserts nothing global — but because `testCaseCounts()` in
 * `system-refusals-reach-testlink.test.ts` snapshots the Test Case counter of
 * every Project, so any sibling that writes a Test Case anywhere moves a number
 * it expects to be still. This file writes one.
 */

/** Where this run's server listens. Its own port: the files beside it use 8131 and 8132. */
const port = Number(process.env.SYSTEM_ABSENCE_TEST_PORT ?? 8133)
const server = `http://127.0.0.1:${port}`

const repository = fileURLToPath(new URL('..', import.meta.url))

/**
 * The fixture this file works in. Its own Project rather than either of the ones
 * the files beside it use, because two of these paths aim a delete at it and a
 * delete that got through would take another file's fixture with it.
 *
 * Stable names, never suffixed: a run that dies before its teardown leaves them
 * findable, so the next run reuses what it finds instead of filling TestLink
 * with near-duplicates. The prefix is stamped into the Project forever and
 * TestLink will not have two, which is another reason not to generate one.
 */
const fixture = {
  project: { name: 'Validator Absence Test', prefix: 'VABX' },
  suite: { name: 'Refused deletes and spent ids' },
  /**
   * The Test Case that must still be there after the two refused deletes. Worded
   * to violate none of the shipped Rules — no colon, no hyphen, none of the
   * terms in `default-rules.sql` — because a Rejection is a 422 and this file is
   * not about what the Rules do. If the Rules grow to catch this, the failure
   * says so: the body of a 422 names the Rule that fired.
   */
  kept: {
    name: 'Guest device holds the open SSID association',
    summary: 'A guest device stays associated with the open SSID while the portal loads.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /**
   * The Test Case placed and removed so that path 3 has an id TestLink issued
   * and has given up, rather than a number picked for being free — a number free
   * today is a number some later run finds taken, and a check against one is a
   * check against arithmetic instead of against absence.
   */
  spent: {
    name: 'Guest device leaves the access point',
    summary: 'A guest device moves out of range and the portal session ends.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /**
   * The Project placed and removed so that path 4 has a Project id TestLink has
   * given up. Its own name and prefix, and removed with the prefix correctly
   * restated — which is the one place in this file a delete is meant to succeed,
   * and the listing afterwards is what settles whether it did.
   */
  spentProject: { name: 'Validator Absence Spent Project', prefix: 'VABS' },
  /**
   * What path 1 restates instead of `VABX`. It has to be a prefix TestLink holds
   * no Project under as well as the wrong one for this Project, so that a
   * TestLink which somehow accepted it could not match anything.
   */
  wrongPrefix: 'NOTVABX',
}

/** What the server answered, kept whole so a failure can quote it. */
interface Answer {
  status: number
  text: string
  body: any
}

async function call(method: string, path: string, payload?: unknown): Promise<Answer> {
  const response = await fetch(`${server}${path}`, {
    method,
    ...(payload === undefined
      ? {}
      : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }),
  })
  const text = await response.text()

  return { status: response.status, text, body: text === '' ? undefined : JSON.parse(text) }
}

/**
 * The answer, or a failure naming what was asked and what came back. Written as
 * a throw rather than an expectation so the same reading works in a hook: a
 * TestLink that is not answering has to say so where it happened, not as an
 * undefined further down.
 */
function answered(what: string, answer: Answer, status: number): Answer {
  if (answer.status !== status) {
    throw new Error(`${what} answered ${answer.status} rather than ${status}: ${answer.text}`)
  }

  return answer
}

/**
 * A listing, reading a Project or a Test Suite that holds nothing yet as the
 * empty listing it is.
 *
 * TestLink reports "is empty" as an API failure rather than as an empty result,
 * and `McpTestLinkClient` matches only "does not exist" and "not found", so that
 * wording escalates as an outage and the server answers 500. That is worth an
 * issue of its own and it is not what this file is about: it shows up only on
 * the way to placing the fixture, on the first run against a TestLink that has
 * never held it. Read here, in the fixture path alone — every answer a path
 * itself reads is demanded outright.
 */
function listed(what: string, answer: Answer): { id: string; name: string }[] {
  if (answer.status === 500 && /is empty/i.test(answer.text)) {
    return []
  }

  return answered(what, answer, 200).body as { id: string; name: string }[]
}

let serverProcess: ChildProcess
/** Everything the server said, so a start that never completes reports its own reason. */
let said = ''
let projectId: string
let suiteId: string
let keptId: string
let spentTestCaseId: string
let spentProjectId: string

/** The real entry point, launched the way `npm run dev` launches it. */
async function startServer(): Promise<void> {
  serverProcess = spawn('npx', ['tsx', '--env-file-if-exists=.env', 'src/server.ts'], {
    cwd: repository,
    // Set here rather than in .env: what is set in the environment wins over the
    // file, so this names the port and the launch without editing anything.
    env: {
      ...process.env,
      PORT: String(port),
      TESTLINK_MCP_COMMAND: process.env.TESTLINK_MCP_COMMAND ?? 'docker',
      TESTLINK_MCP_ARGS:
        process.env.TESTLINK_MCP_ARGS ??
        JSON.stringify([
          'run',
          '--rm',
          '-i',
          '--network',
          'host',
          '-e',
          'TESTLINK_URL',
          '-e',
          'TESTLINK_API_KEY',
          `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
        ]),
    },
    // Its own group, so stopping it stops the testlink-mcp it spawned as well.
    detached: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })

  serverProcess.stdout?.on('data', (chunk) => (said += chunk))
  serverProcess.stderr?.on('data', (chunk) => (said += chunk))

  // Readiness is asked of the route that reads only the database, so a TestLink
  // that is down is reported by the step that needed it rather than as a server
  // that never started.
  for (let attempt = 0; attempt < 120; attempt++) {
    if (serverProcess.exitCode !== null) {
      throw new Error(`The server exited with ${serverProcess.exitCode} before it listened: ${said}`)
    }

    try {
      await call('GET', '/reference-documents')
      return
    } catch {
      await new Promise((wait) => setTimeout(wait, 500))
    }
  }

  throw new Error(`The server did not listen on ${port}: ${said}`)
}

function stopServer(): void {
  if (serverProcess?.pid !== undefined && serverProcess.exitCode === null) {
    try {
      process.kill(-serverProcess.pid, 'SIGTERM')
    } catch {
      serverProcess.kill('SIGTERM')
    }
  }
}

/** Every Project TestLink holds, by id. What paths 1, 2 and 4 read to settle their claim. */
async function projectIds(): Promise<string[]> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)

  return (projects.body as { id: string }[]).map((project) => String(project.id))
}

/** A Project held under a name, reused where TestLink already has one. */
async function placeProject(named: { name: string; prefix: string }, why: string): Promise<string> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)
  const held = (projects.body as { id: string; name: string }[]).find(
    (project) => project.name === named.name,
  )

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Project ${named.name}`,
    await call('POST', '/projects', { ...named, notes: why }),
    201,
  )

  return String(created.body.id)
}

/** The fixture Test Suite under the fixture Project, reused the same way. */
async function placeSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.suite.name)

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Test Suite ${fixture.suite.name}`,
    await call('POST', `/projects/${projectId}/suites`, {
      ...fixture.suite,
      details: 'Fixture Test Suite for the system test that checks what a refused delete leaves behind.',
    }),
    201,
  )

  return String(created.body.id)
}

/** What TestLink's own tree reports the fixture Test Suite holds, by name. */
async function namesInSuite(): Promise<string[]> {
  return listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  ).map((held) => held.name)
}

/** And by id, which is what path 3 needs to say the spent one is gone and the kept one is not. */
async function idsInSuite(): Promise<string[]> {
  return listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  ).map((held) => String(held.id))
}

/**
 * A Test Case one of this file's fixture names is already on, from a run that
 * failed before its teardown. Removed rather than written beside, so the writes
 * below are the only ones under those names and a leak cannot accumulate.
 */
async function removeLeftovers(): Promise<void> {
  const cases = listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  )

  for (const held of cases) {
    if (held.name === fixture.kept.name || held.name === fixture.spent.name) {
      answered(
        `Removing the leftover Test Case ${held.id}`,
        await call('DELETE', `/test-cases/${held.id}`),
        204,
      )
    }
  }
}

/** The Test Case the refused deletes must leave alone. */
async function placeKept(): Promise<string> {
  const written = answered(
    `Writing the Test Case ${fixture.kept.name}`,
    await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.kept),
    201,
  )

  return String(written.body.id)
}

/**
 * A Test Case id TestLink no longer holds. Written into the fixture Test Suite
 * and removed again, because absence has to be something TestLink demonstrated
 * rather than something this file assumed.
 *
 * The removal is demanded and then read back, because an id whose Test Case is
 * still there would prove the opposite of what path 3 needs and would do it
 * silently. Reading it back here is not the same claim path 3 makes: this asks
 * whether the fixture is fit, and it asks it through the Test Suite's listing
 * rather than through the read route path 3 is about.
 */
async function placeAndRemoveTestCase(): Promise<string> {
  const written = answered(
    `Writing the Test Case ${fixture.spent.name}`,
    await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.spent),
    201,
  )
  const id = String(written.body.id)

  answered(`Removing Test Case ${id}`, await call('DELETE', `/test-cases/${id}`), 204)

  if ((await idsInSuite()).includes(id)) {
    throw new Error(`Test Case ${id} is still in Test Suite ${suiteId}, so its id is not spent.`)
  }

  return id
}

/**
 * A Project id TestLink no longer holds. Placed and then removed with its own
 * prefix correctly restated — the one delete in this file that is meant to get
 * through, and the Project listing afterwards is what settles whether it did.
 */
async function placeAndRemoveProject(): Promise<string> {
  const id = await placeProject(
    fixture.spentProject,
    'Placed and removed by the system test, so that its id is one TestLink holds no Project under.',
  )

  answered(
    `Removing Project ${id} with its own prefix restated`,
    await call('DELETE', `/projects/${id}?confirmPrefix=${fixture.spentProject.prefix}`),
    204,
  )

  if ((await projectIds()).includes(id)) {
    throw new Error(`Project ${id} is still in TestLink, so its id is not spent.`)
  }

  return id
}

describe('what a refused delete leaves behind, and what a spent id is answered with', () => {
  beforeAll(async () => {
    await startServer()
    projectId = await placeProject(
      fixture.project,
      'Fixture Project for the system test that checks what a refused delete leaves behind.',
    )
    suiteId = await placeSuite()
    await removeLeftovers()
    keptId = await placeKept()
    spentTestCaseId = await placeAndRemoveTestCase()
    spentProjectId = await placeAndRemoveProject()
  }, 180_000)

  afterAll(async () => {
    try {
      if (keptId !== undefined) {
        answered(
          `Removing the Test Case ${keptId} this run created`,
          await call('DELETE', `/test-cases/${keptId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${keptId}`,
          await call('GET', `/test-cases/${keptId}`),
          404,
