    // only one that went. A read aimed at a spent id must not disturb what is
    // held beside it, and the kept Test Case is what says so.
    expect(await idsInSuite()).toContain(keptId)
    expect(await namesInSuite()).not.toContain(fixture.spent.name)
  }, 60_000)

  it('refuses to update a Project TestLink does not hold, and revives nothing', async () => {
    const before = await projectIds()
    expect(before).not.toContain(spentProjectId)

    const answer = await call('PUT', `/projects/${spentProjectId}`, {
